import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-03-15","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-03-15","date":"2023-03-15T00:00:00.000Z","updated":"2023-03-16T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","测试覆盖率","多部分上传修复","归档区域"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-15.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-15.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-15.md"};function n(s,e,l,_,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p>本次会议主要围绕Ceph RGW的多部分上传修复测试覆盖率和归档区域的请求进行了讨论。</p><h4 id="多部分上传修复测试覆盖率" tabindex="-1">多部分上传修复测试覆盖率 <a class="header-anchor" href="#多部分上传修复测试覆盖率" aria-label="Permalink to &quot;多部分上传修复测试覆盖率&quot;">​</a></h4><ul><li><strong>主要议题：</strong> 讨论了多部分上传功能中避免数据和索引条目泄露的修复工作。该修复已合并到Reef版本中，但缺少针对孤立对象的测试覆盖。</li><li><strong>决定事项：</strong> Eric自愿负责编写测试脚本，该脚本将模拟多部分上传和重新上传操作，并扫描RADOS对象和桶索引以检查是否有泄露的对象和索引条目。</li><li><strong>后续行动计划：</strong> Eric将更新跟踪器问题58780，详细说明测试计划，并讨论在每次RGW验证作业后扫描孤立对象的建议。</li></ul><h4 id="归档区域请求" tabindex="-1">归档区域请求 <a class="header-anchor" href="#归档区域请求" aria-label="Permalink to &quot;归档区域请求&quot;">​</a></h4><ul><li><strong>主要议题：</strong> 讨论了一个长期存在的请求，即归档区域在对象元数据更改时生成新版本的问题。</li><li><strong>决定事项：</strong> 决定不采用快速修复方案，而是考虑更长期的解决方案，如内容可寻址的对象表示方法，这可能会提高RADOS对象名称的信息密度，并增加系统的灵活性。</li><li><strong>后续行动计划：</strong> 将在周一的会议上进一步讨论此问题，并在Upstream邮件列表中启动关于设计想法的讨论。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>讨论了其他可能的改进方向，如基于块的内容可寻址块，这可能对大型对象特别有用。</li></ul><p><strong>会议总结：</strong> 本次会议重点讨论了多部分上传修复的测试覆盖和归档区域的长期解决方案，确定了具体的行动计划和后续讨论的方向。</p>',9)])])}const g=t(i,[["render",n]]);export{d as __pageData,g as default};
